def get_book_info_ui(book_title):
    if not book_title:
        return {"error": "Book title is required"}

    book = frappe.db.get_value(
        "Book Doctype",
        {"book_title": book_title},
        ["author", "isbn", "shelf", "publisher", "publication_year", "description"],
        as_dict=True
    )

    if not book:
        return {"error": "Book not found"}

    return book
